const results = [];
for (const item of $input.all()) {
  let text = "";
  const content = item.json.content;
  if (Array.isArray(content)) {
    for (const block of content) {
      if (block.type === "text") {
        text += block.text;
      }
    }
  } else if (typeof content === "string") {
    text = content;
  }
  text = text.replace(/```json|```/g, "").trim();
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    data = { status: "bad_format", content: text, reason: "Could not read as JSON" };
  }
  results.push({
    json: {
      status: data.status || "",
      content: data.content || "",
      reason: data.reason || ""
    }
  });
}
return results;

const writer = $('Parse writer output').first().json;
const form = $('Content request form').first().json;
const results = [];
for (const item of $input.all()) {
  let text = "";
  const content = item.json.content;
  if (Array.isArray(content)) {
    for (const block of content) {
      if (block.type === "text") {
        text += block.text;
      }
    }
  } else if (typeof content === "string") {
    text = content;
  }
  text = text.replace(/```json|```/g, "").trim();
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    data = { verdict: "bad_format", problems: [text] };
  }
  const problems = Array.isArray(data.problems) ? data.problems.join(" | ") : String(data.problems || "");
  results.push({
    json: {
      request: form.Request,
      status: writer.status,
      content: writer.content,
      reason: writer.reason,
      verdict: data.verdict || "",
      problems: problems
    }
  });
}
return results;

const original = $('Set final status').first().json;
let text = "";
const content = $input.first().json.content;
if (Array.isArray(content)) {
  for (const block of content) {
    if (block.type === "text") {
      text += block.text;
    }
  }
} else if (typeof content === "string") {
  text = content;
}
text = text.replace(/```json|```/g, "").trim();
let translation = "";
try {
  translation = JSON.parse(text).translation || "";
} catch (e) {
  translation = "";
}
return [{ json: { ...original, translation: translation } }];
